#!/usr/bin/env python3
"""Reserve one paid Higgsfield generation under the lane caps, atomically.

gen.sh used to count the ledger and then append, with nothing in between: two
runs starting together both passed the same check and both spent a generation,
so the 9-total / 3-per-concept caps could be overshot. Counting and appending
now happen while holding an exclusive lock on the ledger, so concurrent runs
queue instead of racing.

Prints the 1-based index for this concept on success. Exit 3 means a cap is
spent, and nothing was written.

Usage: reserve.py <ledger-path> <concept> [total-cap] [per-cap]
"""

import fcntl
import os
import sys
from datetime import UTC, datetime


def reserve(ledger: str, concept: str, total_cap: int = 9, per_cap: int = 3) -> int:
    """Append one reservation row for `concept` and return its per-concept index.

    Raises SystemExit(3) when either cap is already spent.
    """
    os.makedirs(os.path.dirname(ledger) or ".", exist_ok=True)
    with open(ledger, "a+") as f:
        fcntl.flock(f, fcntl.LOCK_EX)  # released when the file closes
        f.seek(0)
        rows = [line.split("\t") for line in f.read().splitlines() if line.strip()]
        total = len(rows)
        per = len([r for r in rows if len(r) > 1 and r[1] == concept])
        if total >= total_cap:
            print(f"CAP: {total_cap} generations already spent", file=sys.stderr)
            raise SystemExit(3)
        if per >= per_cap:
            print(
                f"CAP: concept {concept} already has {per_cap} generations",
                file=sys.stderr,
            )
            raise SystemExit(3)
        index = per + 1
        stamp = datetime.now(UTC).strftime("%Y-%m-%dT%H:%M:%SZ")
        f.write(f"{stamp}\t{concept}\t{index}\tsubmitted\n")
        f.flush()
        os.fsync(f.fileno())
    return index


def main() -> None:
    """CLI wrapper: reserve.py <ledger> <concept> [total-cap] [per-cap]."""
    if len(sys.argv) < 3:
        sys.exit(__doc__)
    ledger, concept = sys.argv[1], sys.argv[2]
    caps = [int(a) for a in sys.argv[3:5]]
    print(reserve(ledger, concept, *caps))


if __name__ == "__main__":
    main()
